argv:
$ErrorActionPreference='Stop'
$dir='E:\boss-R65-CANARY-VERIFY-20261014-GPT6'
$sha=([string](& git.exe -C $dir rev-parse HEAD)).Trim()
if($sha -ne 'ff6b105fde40e3e292c883073f741b4970523ff2'){throw ('EXACT_SHA_MISMATCH '+$sha)}
if(-not(Test-Path -LiteralPath (Join-Path $dir 'tests\r65_autonomy_canary.test.cjs'))){throw 'MISSING_TEST'}
$log=Join-Path $dir 'QA_NODE_TEST_RESULT_GPT6_20261014.txt'
Push-Location -LiteralPath $dir
try { & node.exe --test tests/r65_autonomy_canary.test.cjs 2>&1 | Out-File -LiteralPath $log -Encoding UTF8; $rc=$LASTEXITCODE } finally { Pop-Location }
Write-Output ('EXACT_SHA='+$sha)
Write-Output ('NODE_EXIT='+$rc)
Select-String -LiteralPath $log -Pattern '^ℹ (?:tests|pass|fail|skipped)|^✖'|Select-Object -Last 16|ForEach-Object {Write-Output $_.Line}
Write-Output ('LOG='+$log)
if($rc -ne 0){throw 'QA_NODE_TEST_FAILED'}
